CREATE DATABASE IF NOT EXISTS trouve_ton_artisan CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE trouve_ton_artisan;
CREATE TABLE IF NOT EXISTS categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,slug VARCHAR(90) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS specialties (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,category_id INT UNSIGNED NOT NULL,CONSTRAINT fk_specialty_category FOREIGN KEY(category_id) REFERENCES categories(id) ON UPDATE CASCADE ON DELETE RESTRICT,INDEX idx_specialty_category(category_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS artisans (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,rating DECIMAL(2,1) NOT NULL,city VARCHAR(120) NOT NULL,about TEXT NOT NULL,email VARCHAR(254) NOT NULL,website VARCHAR(255) NULL,image VARCHAR(255) NULL,is_top BOOLEAN NOT NULL DEFAULT FALSE,specialty_id INT UNSIGNED NOT NULL,CONSTRAINT chk_rating CHECK(rating BETWEEN 0 AND 5),CONSTRAINT fk_artisan_specialty FOREIGN KEY(specialty_id) REFERENCES specialties(id) ON UPDATE CASCADE ON DELETE RESTRICT,INDEX idx_artisan_name(name),INDEX idx_artisan_specialty(specialty_id),INDEX idx_artisan_top(is_top)) ENGINE=InnoDB;
